package br.com.andre22bodybuilder.meufinanceiro;
import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;
public class QuickEntryActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);String type=getIntent().getStringExtra("type");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,28,40,28);l.setBackgroundColor(Color.rgb(16,21,18));TextView t=new TextView(this);t.setText("in".equals(type)?"Nova entrada":"Nova saída");t.setTextSize(22);t.setTextColor("in".equals(type)?Color.rgb(53,245,106):Color.rgb(255,83,98));l.addView(t);EditText d=new EditText(this);d.setHint("Descrição");d.setTextColor(Color.WHITE);d.setHintTextColor(Color.GRAY);l.addView(d);EditText v=new EditText(this);v.setHint("Valor");v.setInputType(2|8192);v.setTextColor(Color.WHITE);v.setHintTextColor(Color.GRAY);l.addView(v);Spinner c=new Spinner(this);String[] cs={"Uber","Consultoria","C+A","Combustível","Alimentação","Manutenção","Contas","Compras","Produtos","Outros"};c.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,cs));l.addView(c);Button s=new Button(this);s.setText("Continuar no Meu Financeiro");final String q="in".equals(type)?"in":"out";s.setOnClickListener(x->{android.content.Intent i=new android.content.Intent(this,MainActivity.class);i.putExtra("quick",q);i.putExtra("qdesc",d.getText().toString());i.putExtra("qvalue",v.getText().toString());i.putExtra("qcat",c.getSelectedItem().toString());startActivity(i);finish();});l.addView(s);setContentView(l);}
}